/*
 * This is a Gulp build script for project automation.
 * It handles various tasks like compiling LESS/SASS,
 * concatenating/minifying JavaScript, generating SVG sprites,
 * and deploying assets.
 */

/*global require, __dirname, console*/ /* Ensure these global variables are recognized */
/*jshint -W079 */ /* Suppress warnings about re-assigning native globals */

var fs          = require("fs")         , /* Node.js file system module */
    path        = require("path")       , /* Node.js path module */
    gulp        = require("gulp")       , /* The main Gulp toolkit */
    gutil       = require("gulp-util")  , /* Gulp utility functions */
    concat      = require("gulp-concat"), /* Concatenates files */
    uglify      = require("gulp-uglify"), /* Minifies JavaScript files */
    less        = require("gulp-less")  , /* Compiles LESS to CSS */
    sass        = require("gulp-sass")  , /* Compiles SASS to CSS */
    minify      = require("gulp-minify-css"), /* Minifies CSS files */
    run         = require("run-sequence"), /* Runs a sequence of Gulp tasks */
    prefix      = require("gulp-autoprefixer"), /* Adds vendor prefixes to CSS */
    svgstore    = require("gulp-svgstore"), /* Combines SVG files into one */
    svgmin      = require("gulp-svgmin")  , /* Minifies SVG files */
    hogan       = require("gulp-hogan-compile"), /* Compiles Hogan templates */
    rename      = require("gulp-rename")  , /* Renames files */
    s3          = require("gulp-s3")      , /* Uploads files to Amazon S3 */
    gzip        = require("gulp-gzip")    , /* Gzips files */
    replace     = require("gulp-replace") , /* Replaces strings in files */
    open        = require("gulp-open")    , /* Opens URLs or files */
    size        = require("gulp-size")    ; /* Reports on file sizes */

// Define the root directory for consistent pathing.
var root = __dirname                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            